      this.plot=new window.LabPlot($('freePlot'),(d,f,c)=>this.cursor(d,c),()=>this.queuePersist());this.bind();this.restoreWorkspace();this.render();try{if(localStorage.getItem('circuit-lab-workspace')==='free')this.open();}catch{}
